 if(signature===model.adjustedSignature||signature===model.pendingSignature)return;
 model.pendingSignature=signature;clearTimeout(previewTimer);
 previewTimer=setTimeout(guarded(async()=>{
  try{const data=await rpc('adjustmentPreview',{options:JSON.parse(signature)});if(!data)return;
   const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error(t('تعذر تجهيز المعاينة','Could not prepare the preview')));image.src=data;});
   if(JSON.stringify(model.options)===signature){model.adjustedImage=image;model.adjustedSignature=signature;requestRender();}
  }finally{if(model.pendingSignature===signature)model.pendingSignature=null;}
 }),180);
