 const choices=state.mode==='pdf'?[['select','select',t('تحديد','Select')],['text','text',t('نص','Text')],['image','image',t('صورة','Image')],['redact','redact',t('حجب','Redact')]]:[['select','select',t('تحديد','Select')],['crop','crop',t('اقتصاص','Crop')],['adjust','sliders',t('ألوان','Color')],['text','text',t('نص','Text')],['draw','pen',t('رسم','Draw')],['redact','redact',t('حجب','Cover')],['rotate','rotate',t('تدوير','Rotate')],['background','palette',t('خلفية','Backdrop')]];
