function colorControls(){const color=state.mode==='pdf'?(inlineEditor?.data.color||pdfStyle.color):model.color;return `<div class="color-swatches">${['#252934','#ffffff','#de655d','#e7b759','#71a789','#6d99d7','#ae8cc7'].map(value=>`<button class="swatch ${color===value?'active':''}" style="background:${value}" data-color="${value}" aria-label="${value}"></button>`).join('')}<input type="color" id="color-picker" value="${color}" aria-label="${t('لون مخصص','Custom color')}"></div>`;}
function setColor(value){if(state.mode==='image')model.color=value;else pdfStyle.color=value;if(inlineEditor){inlineEditor.data.color=value;inlineEditor.element.style.color=value;}$('inspector').querySelectorAll('[data-color]').forEach(button=>button.classList.toggle('active',button.dataset.color===value));}
function position(event){const r=$('stage').getBoundingClientRect();return {x:Math.max(0,Math.min(1,(event.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(event.clientY-r.top)/r.height))};}
function rectBetween(a,b){return {x:Math.min(a.x,b.x),y:Math.min(a.y,b.y),w:Math.abs(b.x-a.x),h:Math.abs(b.y-a.y)};}
async function pointerDown(event){if(event.button!==0||event.target.closest('.inline-text'))return;event.preventDefault();const previousTarget=state.mode==='pdf'?pdf.elements.find(e=>e.id===Number(event.target.dataset.element)):null;await commitInline();const p=position(event),stage=$('stage');
 if(state.mode==='pdf'){
  let id=event.target.dataset.element;if(previousTarget){const candidates=pdf.elements.filter(e=>e.kind===previousTarget.kind);const exact=candidates.find(e=>e.text===previousTarget.text&&e.rect.every((v,i)=>Math.abs(v-previousTarget.rect[i])<2));const closest=exact||candidates.sort((a,b)=>a.rect.reduce((n,v,i)=>n+Math.abs(v-previousTarget.rect[i]),0)-b.rect.reduce((n,v,i)=>n+Math.abs(v-previousTarget.rect[i]),0))[0];if(closest)id=String(closest.id);}if(activeTool==='redact'){dragging={kind:'pdf-redact',start:p};stage.setPointerCapture(event.pointerId);cropBox={...p,w:0,h:0};renderCrop();return;}
  if(id!==undefined){const element=pdf.elements.find(e=>e.id===Number(id));if(element?.kind==='text'){selectedPdfId=null;beginInline({...element,rect:[...element.rect]},event);return;}if(element?.kind==='image'){selectedPdfId=element.id;dragging={kind:'pdf-move',start:p,rect:[...element.rect],id:element.id};stage.setPointerCapture(event.pointerId);event.target.classList.add('selected-image');renderInspector();return;}}selectedPdfId=null;
  if(activeTool==='text'){const x=p.x*pdf.width,y=p.y*pdf.height;beginInline({id:null,text:'',size:pdfStyle.size,color:pdfStyle.color,rect:[x,y,Math.min(pdf.width-4,x+220),Math.min(pdf.height-4,y+40)]},event);}return;
 }
 if(activeTool==='text'){const hit=hitOperation(p);if(hit>=0&&model.operations[hit].type==='text'){beginImageText(hit,event);return;}checkpoint();const op={type:'text',x:p.x,y:p.y,text:'',size:model.textSize,color:model.color,textWidth:.3};model.operations.push(op);beginImageText(model.operations.length-1,event);return;}
 if(activeTool==='crop'){dragging={kind:'crop',start:p};cropBox={...p,w:0,h:0};stage.setPointerCapture(event.pointerId);renderCrop();return;}
 if(['draw','redact'].includes(activeTool)){checkpoint();const op=activeTool==='redact'?{type:'redact',box:[p.x,p.y,0,0],color:model.color,effect:model.effect||'solid'}:model.shape==='pen'?{type:'pen',points:[[p.x,p.y]],color:model.color,width:model.stroke}:{type:model.shape,x1:p.x,y1:p.y,x2:p.x,y2:p.y,color:model.color,width:model.stroke};model.operations.push(op);dragging={kind:'draw',start:p,index:model.operations.length-1};stage.setPointerCapture(event.pointerId);return;}
 const hit=hitOperation(p);selectedOp=hit;if(hit>=0){if(model.operations[hit].type==='text'){beginImageText(hit,event);return;}checkpoint();dragging={kind:'move',start:p,index:hit,original:clone(model.operations[hit])};stage.setPointerCapture(event.pointerId);}requestRender();
}
function pointerMove(event){if(!dragging)return;const p=position(event),d=dragging;if(d.kind==='pdf-move'){const target=$('stage').querySelector(`[data-element="${d.id}"]`);if(target){target.style.translate=`${(p.x-d.start.x)*$('stage').clientWidth}px ${(p.y-d.start.y)*$('stage').clientHeight}px`;}d.dx=(p.x-d.start.x)*pdf.width;d.dy=(p.y-d.start.y)*pdf.height;return;}
 if(['crop','pdf-redact'].includes(d.kind)){cropBox=rectBetween(d.start,p);if(d.kind==='crop'&&model.aspect){const ratio=model.aspect*model.previewHeight/model.previewWidth;cropBox.h=Math.min(1-cropBox.y,cropBox.w/ratio);cropBox.w=cropBox.h*ratio;}renderCrop();return;}
 const op=model.operations[d.index];if(d.kind==='move'){const dx=p.x-d.start.x,dy=p.y-d.start.y;Object.assign(op,clone(d.original));for(const key of ['x','x1','x2'])if(key in op)op[key]+=dx;for(const key of ['y','y1','y2'])if(key in op)op[key]+=dy;if(op.points)op.points=op.points.map(([x,y])=>[x+dx,y+dy]);if(op.box){op.box[0]+=dx;op.box[1]+=dy;}}
 else if(op.type==='pen')op.points.push([p.x,p.y]);else if(op.type==='redact'){const b=rectBetween(d.start,p);op.box=[b.x,b.y,b.w,b.h];}else{op.x2=p.x;op.y2=p.y;}requestRender();
}
async function pointerUp(){if(!dragging)return;const d=dragging;dragging=null;if(d.kind==='pdf-move'){if(Math.abs(d.dx||0)+Math.abs(d.dy||0)>1){pdf=await rpc('pdfMove',{id:d.id,rect:d.rect.map((value,i)=>value+(i%2===0?d.dx:d.dy))});selectedPdfId=null;renderPdfStage();renderInspector();}return;}if(d.kind==='pdf-redact'){const b=cropBox;cropBox=null;if(b&&b.w>0.005&&b.h>0.005){pdf=await rpc('pdfRedact',{rect:[b.x*pdf.width,b.y*pdf.height,(b.x+b.w)*pdf.width,(b.y+b.h)*pdf.height]});renderPdfStage();}renderCrop();return;}if(d.kind!=='crop')changed();}
function opBounds(op){if(!op)return null;if(op.type==='text')return{x:op.x,y:op.y,w:op.textWidth||.25,h:op.size*model.previewWidth/model.previewHeight*1.35};if(op.box){const[x,y,w,h]=op.box;return{x,y,w,h};}if('x1'in op)return rectBetween({x:op.x1,y:op.y1},{x:op.x2,y:op.y2});if(op.points){const x=op.points.map(p=>p[0]),y=op.points.map(p=>p[1]);return{x:Math.min(...x),y:Math.min(...y),w:Math.max(...x)-Math.min(...x),h:Math.max(...y)-Math.min(...y)};}return null;}
function hitOperation(point){for(let i=model.operations.length-1;i>=0;i--){if(['crop','rotate','flip','background'].includes(model.operations[i].type))continue;const b=opBounds(model.operations[i]);if(b&&point.x>=b.x-.01&&point.x<=b.x+b.w+.01&&point.y>=b.y-.01&&point.y<=b.y+b.h+.01)return i;}return-1;}
function renderCrop(){document.querySelector('.crop-box')?.remove();if(!cropBox||!$('stage'))return;const box=document.createElement('div');box.className='crop-box';box.style.cssText=`left:${cropBox.x*100}%;top:${cropBox.y*100}%;width:${cropBox.w*100}%;height:${cropBox.h*100}%`;box.innerHTML='<i></i><i></i><i></i><i></i>';$('stage').append(box);if($('apply-crop'))$('apply-crop').disabled=cropBox.w<.005||cropBox.h<.005;}
function applyCrop(){if(!cropBox||cropBox.w<.005||cropBox.h<.005)return;checkpoint();const b=cropBox;model.operations.push({type:'crop',box:[b.x,b.y,b.w,b.h]});cropBox=null;selectedOp=-1;changed();}
function beginImageText(index,event){const op=model.operations[index];inlineEditor={data:clone(op),opIndex:index,isNew:!op.text};if(op.text)checkpoint();makeInline(event);requestRender();}
function beginInline(data,event){pdfStyle.size=data.size;pdfStyle.color=data.color;inlineEditor={data,original:clone(data)};makeInline(event);renderInspector();}
function makeInline(event){const edit=document.createElement('div');edit.className='inline-text'+(state.mode==='pdf'?' pdf-inline':'');edit.contentEditable='true';edit.spellcheck=false;edit.dir='auto';edit.setAttribute('aria-label',t('تعديل النص في مكانه','Edit text in place'));edit.textContent=inlineEditor.data.text||'';inlineEditor.element=edit;$('stage').append(edit);positionInline();edit.addEventListener('input',()=>{inlineEditor.data.text=edit.innerText.replace(/\n$/,'');if(state.mode==='image'){const c=$('canvas').getContext('2d');c.font=`${inlineEditor.data.size*model.previewWidth}px Segoe UI`;inlineEditor.data.textWidth=Math.max(.05,c.measureText(inlineEditor.data.text).width/model.previewWidth);}positionInline();});edit.addEventListener('blur',()=>{setTimeout(()=>{if(inlineEditor?.element===edit&&!$('inspector').contains(document.activeElement))guarded(commitInline)();},120);});edit.addEventListener('keydown',event=>{event.stopPropagation();if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();guarded(save)();return;}if(event.key==='Escape'){cancelInline();}if((event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();guarded(commitInline)();}});edit.focus();const selection=getSelection();const range=document.createRange();range.selectNodeContents(edit);range.collapse(false);selection.removeAllRanges();selection.addRange(range);if(event&&document.caretRangeFromPoint){const caret=document.caretRangeFromPoint(event.clientX,event.clientY);if(caret&&edit.contains(caret.startContainer)){selection.removeAllRanges();selection.addRange(caret);}}}
function positionInline(){if(!inlineEditor?.element)return;const edit=inlineEditor.element,data=inlineEditor.data,w=$('stage').clientWidth,h=$('stage').clientHeight;if(state.mode==='pdf'){const[x0,y0,x1,y1]=data.rect;edit.style.cssText=`left:${x0/pdf.width*100}%;top:${y0/pdf.height*100}%;width:${(x1-x0)/pdf.width*100}%;min-height:${(y1-y0)/pdf.height*100}%;font-size:${data.size*w/pdf.width}px;color:${data.color};`;}else{edit.style.cssText=`left:${data.x*100}%;top:${data.y*100}%;min-width:60px;max-width:${(1-data.x)*100}%;font-size:${data.size*w}px;color:${data.color};`;}}
async function commitInline(){if(pendingCommit)return pendingCommit;if(!inlineEditor)return true;const current=inlineEditor;current.data.text=current.element.innerText.replace(/\n$/,'');pendingCommit=(async()=>{try{if(state.mode==='pdf'){const original=current.original;if(original&&current.data.id!==null&&current.data.text===original.text&&current.data.size===original.size&&current.data.color===original.color){inlineEditor=null;current.element.remove();renderInspector();return true;}if(current.data.id!==null||current.data.text.trim()){const response=await rpc('pdfText',current.data);inlineEditor=null;current.element.remove();pdf=response;renderPdfStage();}else{inlineEditor=null;current.element.remove();}}else{if(current.data.text.trim()){model.operations[current.opIndex]=clone(current.data);delete model.operations[current.opIndex].isNew;changed();}else{model.operations.splice(current.opIndex,1);}inlineEditor=null;current.element.remove();requestRender();}return true;}catch(error){current.element.focus();throw error;}finally{queueMicrotask(()=>{pendingCommit=null;});}})();return pendingCommit;}
function cancelInline(){if(!inlineEditor)return;const current=inlineEditor;inlineEditor=null;current.element.remove();if(state.mode==='image'){if(current.isNew)model.operations.splice(current.opIndex,1);requestRender();}}
function pdfEditor(){pdf=state.pdf;editorShell();renderPdfStage();setTool('select');}
function renderPdfStage(){selectedPdfId=null;const stage=$('stage');stage.className='stage pdf-stage';stage.innerHTML=`<img src="${pdf.image}" draggable="false" alt="${t('صفحة PDF','PDF page')}">`;for(const element of pdf.elements){const target=document.createElement('div');target.className='pdf-text-target'+(element.kind==='image'?' pdf-image-target':'');target.dataset.element=element.id;target.title=t('انقر واكتب مباشرة','Click to edit in place');const[x0,y0,x1,y1]=element.rect;target.style.cssText=`left:${x0/pdf.width*100}%;top:${y0/pdf.height*100}%;width:${(x1-x0)/pdf.width*100}%;height:${(y1-y0)/pdf.height*100}%`;stage.append(target);}
 $('pages').innerHTML='';for(let i=0;i<pdf.count;i++){const button=document.createElement('button');button.className='page-thumb'+(pdf.page===i?' active':'');button.innerHTML=icon('file')+`<span>${i+1}</span>`;button.onclick=guarded(async()=>{await commitInline();pdf=await rpc('pdfPage',{page:i});renderPdfStage();});$('pages').append(button);}const controls=document.createElement('div');controls.className='page-controls';for(const[method,symbol,label]of[['pdfRotate','rotate',t('تدوير الصفحة','Rotate page')],['pdfDuplicate','copy',t('تكرار الصفحة','Duplicate page')],['pdfDeletePage','trash',t('حذف الصفحة','Delete page')]]){const button=document.createElement('button');button.className='round glass';button.innerHTML=icon(symbol);button.title=label;button.disabled=method==='pdfDeletePage'&&pdf.count===1;button.onclick=guarded(async()=>{await commitInline();pdf=await rpc(method);renderPdfStage();});controls.append(button);}$('pages').append(controls);resizeStage();updateHistory();renderInspector();}
async function save(){
 if(state.mode==='audio')return saveAudio();
 if(saving)return;saving=true;
 $('save').disabled=true;$('save').querySelector('span').textContent=t('جارٍ الحفظ…','Saving…');
 try{
  await commitInline();
  if(state.mode==='pdf'){lastSaved=await rpc('pdfSave');pdf.dirty=false;return lastSaved;}
  const revision=model.revision;
  const saved=new Promise((resolve,reject)=>{saveResolve=resolve;saveReject=reject;});
  await rpc('saveImage',{format:$('export-format').value.toLowerCase(),options:model.options,operations:model.operations});
  lastSaved=await saved;if(model.revision===revision)model.dirty=false;return lastSaved;
 }finally{saving=false;saveResolve=saveReject=null;$('save').disabled=false;$('save').querySelector('span').textContent=t('حفظ نسخة','Save a copy');}
}
function commands(){const options=[{label:t('فتح ملف','Open a file'),symbol:'folder',run:pick},{label:t('الإعدادات','Settings'),symbol:'settings',run:()=>rpc('settings')}];if(currentFile){options.push({label:t('فتح في المحرر','Open in editor'),symbol:'pen',run:editFile});for(const tool of fileOptions?.tools||[])options.push({label:tool.label,symbol:toolIcon(tool.id),run:()=>rpc('tool',{files:workspaceFiles().map(file=>file.path),key:tool.id})});}return options;}
function openCommands(){if(state.mode!=='home')return;$('command-backdrop').hidden=false;$('command-input').value='';renderCommands('');$('command-input').focus();}
function renderCommands(query){const results=$('command-results');results.replaceChildren();for(const item of commands().filter(item=>item.label.toLowerCase().includes(query.toLowerCase()))){const button=document.createElement('button');button.innerHTML=icon(item.symbol)+`<span>${esc(item.label)}</span>`;button.onclick=guarded(async()=>{$('command-backdrop').hidden=true;await item.run();});results.append(button);}if(!results.children.length)results.innerHTML=`<small>${t('ما لقينا هذا الأمر. جرّب كلمة ثانية.','No matching action. Try another word.')}</small>`;}
document.addEventListener('keydown',guarded(async event=>{const mod=event.ctrlKey||event.metaKey;if(mod&&event.key.toLowerCase()==='s'&&state.mode!=='home'){event.preventDefault();await save();}else if(mod&&event.key.toLowerCase()==='o'){event.preventDefault();if(state.mode==='home')await pick();}else if(mod&&event.key.toLowerCase()==='k'){event.preventDefault();openCommands();}else if(mod&&event.key.toLowerCase()==='z'&&['image','pdf'].includes(state.mode)&&!event.target.isContentEditable){event.preventDefault();event.shiftKey?await redo():await undo();}else if(mod&&event.key.toLowerCase()==='y'&&['image','pdf'].includes(state.mode)&&!event.target.isContentEditable){event.preventDefault();await redo();}else if(event.key==='Escape'){$('command-backdrop').hidden=true;if(inlineEditor)cancelInline();else if(cropBox){cropBox=null;renderCrop();}}else if(event.code==='Backslash'&&state.mode==='image'&&!event.target.isContentEditable){compare(true);}else if(event.key==='Delete'&&state.mode==='image'&&selectedOp>=0&&!event.target.isContentEditable){checkpoint();model.operations.splice(selectedOp,1);selectedOp=-1;changed();}}));
document.addEventListener('keyup',event=>{if(event.code==='Backslash'&&state?.mode==='image')compare(false);});
$('command-input').addEventListener('input',event=>renderCommands(event.target.value));$('command-backdrop').addEventListener('pointerdown',event=>{if(event.target===$('command-backdrop'))$('command-backdrop').hidden=true;});
new QWebChannel(qt.webChannelTransport,channel=>{native=channel.objects.studio;native.response.connect((id,message)=>{const pending=requests.get(id);if(!pending)return;requests.delete(id);const data=JSON.parse(message);data.ok?pending.resolve(data.value):pending.reject(new Error(data.error));});native.event.connect((name,message)=>{const data=JSON.parse(message);if(name==='task'){ActivityUI.update(data);}else if(name==='theme'&&state){state.dark=data.dark;document.body.classList.toggle('dark',data.dark);for(const[key,value]of Object.entries(data.design))document.documentElement.style.setProperty('--'+key,value);if(state.mode==='audio')drawAudio();}else if(name==='files'&&state?.mode==='home'){state.files=data;home();}else if(name==='audioReady'){setAudioData(data);}else if(name==='audioPosition'){updateAudioPosition(data);}else if(name==='audioError'){audioFailure(data.message);}else if(name==='saved'){lastSaved=data.path;toast(t('تم الحفظ: ','Saved: ')+data.path.split(/[\\/]/).pop(),data.path);saveResolve?.(data.path);saveResolve=saveReject=null;}else if(name==='error'){saveReject?.(new Error(data.message));toast(data.message);}});guarded(async()=>{state=await rpc('init');ar=state.language==='ar';document.documentElement.dir=ar?'rtl':'ltr';document.documentElement.lang=ar?'ar':'en';document.body.classList.toggle('dark',state.dark);for(const [key,value]of Object.entries(state.design||{}))document.documentElement.style.setProperty('--'+key,value);setupHeader();ActivityUI.init(state.tasks||[]);if(state.mode==='home'){home();ActivityUI.notice(t('جاهز لملفاتك · اسحب ملفًا للبدء','Ready for your files · Drop a file to begin'));}else if(state.mode==='image')await imageEditor();else if(state.mode==='audio')audioEditor();else pdfEditor();})();});
